    "commentary": "본문(로마서 12:12)은 지치고 곤비한 우리 영혼을 향한 주님을 앙망할 때 주어지는 새 힘과 회복의 약속입니다.\n인간의 체력과 지혜는 한계가 있어 넘어지고 피곤하지만, 온 우주를 창조하시고 피곤치 아니하시는 여호와를 앙망하는 자는 날마다 독수리 날개 치듯 새 힘을 얻습니다.\n\n내 힘으로 버티려 하지 말고 주님의 보좌 앞에 나아가 은혜를 구할 때, 성령의 충만한 능력으로 세상을 넉넉히 이길 담대함이 부어집니다.",
